# All headless coop smoke tests (milestones M0 onward). Usage (from the repo root):
#   powershell -ExecutionPolicy Bypass -File scripts/coop/smoke.ps1 [-Only S5,S10]
# Every test must end with SMOKE PASS; the script prints one line per test and exits 1 if any failed.
# Notes: the host only runs game frames after a command following the map load (hence -HostAfterMap
# '+wait 100' where host frames matter), and kejim_post's intro cutscene blocks saving unless it is
# sped up with timescale.
param([string[]]$Only = @())
$ErrorActionPreference = "Stop"
$Only = @($Only | ForEach-Object { $_ -split "," } | Where-Object { $_ })
$link = "-HostArgs '+coop_host' -GuestArgs '+coop_connect 127.0.0.1:29170'"
$tests = [ordered]@{
  S0  = "-NoGuest -Seconds 20 -ExpectHost 'Server: kejim_post' -RejectHost 'COOP: '"
  S1  = "-Seconds 25 $link -ExpectHost 'COOP: hosting on UDP port 29190','COOP: link up','COOP: hello from GuestBot' -ExpectGuest 'COOP: link up','COOP: hello from HostBot' -RejectHost 'link closed','overflowed' -RejectGuest 'link closed','overflowed'"
  S2  = "-Seconds 25 -HostArgs '+coop_host' -GuestArgs '+set coop_autotest 60000','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: test payload 60000 bytes ok' -ExpectGuest 'COOP: test payload 60000 bytes sent' -RejectHost 'corrupt','link closed' -RejectGuest 'link closed','overflowed'"
  S3  = "-Seconds 40 -HostArgs '+set coop_simLoss 10','+set coop_simLatency 80','+coop_host' -GuestArgs '+set coop_simLoss 10','+set coop_simLatency 80','+set coop_autotest 3000','+set coop_autotestCount 40','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: link up','COOP: hello from GuestBot','COOP: test payload 3000 bytes ok' -ExpectGuest 'COOP: link up','COOP: hello from HostBot','COOP: test payload 3000 bytes sent' -RejectHost 'link closed','corrupt' -RejectGuest 'link closed','overflowed'"
  S4  = "-Seconds 40 -HostArgs '+set coop_onlink coop_reloadmap','+coop_host' -GuestArgs '+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: link up','COOP: map load started, peer notified','COOP: map loaded, peer notified' -ExpectGuest 'COOP: peer is loading a map','COOP: peer finished loading' -RejectHost 'link closed' -RejectGuest 'link closed'"
  S5  = "-Seconds 45 -HostArgs '+set coop_timeout 5','+coop_host' -GuestArgs '+set coop_timeout 5','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: game mode host','COOP: guest entered kejim_post' -ExpectGuest 'COOP: loading kejim_post from host','Server: kejim_post','COOP: in kejim_post, waiting','COOP: game mode guest' -RejectHost 'link closed','no free entities' -RejectGuest 'link closed','no free entities'"
  S6  = "-NoGuest -Seconds 50 -HostAfterMap '+set timescale 8','+wait 2000','+set timescale 1','+save cooptest','+wait 300','+load cooptest' -ExpectHost 'Saving game .cooptest','Loading game .cooptest' -RejectHost 'Failed\.','has version','Can.t savegame'"
  S7  = "-Seconds 45 $link -ExpectHost 'COOP: guest entered kejim_post' -ExpectGuest 'COOP: configstrings synced \(\d{2,} strings\)' -RejectHost 'link closed','overflowed' -RejectGuest 'link closed','Server command overflow','overflowed'"
  S8  = "-Seconds 45 -HostArgs '+set coop_onworld coop_ents','+coop_host' -GuestArgs '+set coop_onworld coop_ents','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: guest entered kejim_post','COOP: entities \d+ \(ours \d+, other 0, clients \d+\)' -ExpectGuest 'COOP: game mode guest','COOP: entities \d+ \(ours \d+, other [1-9]\d*, clients 1\)' -RejectHost 'link closed' -RejectGuest 'link closed'"
  S9  = "-NoGuest -Seconds 20 -HostArgs '+coop_host' -HostAfterMap '+coop_entinfo 2' -ExpectHost 'COOP: game mode host','COOP: entinfo 2 owner 1 class \S+'"
  S10 = "-Seconds 50 $link -HostAfterMap '+wait 100' -ExpectHost 'COOP: guest entered kejim_post' -ExpectGuest 'COOP: configstrings synced','COOP: world synced \(\d+ entities, \d+ npcs\)' -RejectHost 'link closed','overflowed' -RejectGuest 'link closed','bad snapshot','layout differs','Server command overflow'"
  S11 = "-Seconds 70 -HostArgs '+set coop_simLoss 10','+set coop_simLatency 80','+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+set coop_simLoss 10','+set coop_simLatency 80','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: guest entered kejim_post' -ExpectGuest 'COOP: world synced' -RejectHost 'link closed' -RejectGuest 'link closed','bad snapshot','Server command overflow'"
  S12 = "-Seconds 60 $link -HostAfterMap '+wait 400','+npc spawn stormtrooper' -ExpectHost 'COOP: guest entered kejim_post' -ExpectGuest 'COOP: world synced \(\d+ entities, [1-9]\d* npcs\)','COOP: replica npc \d+ \(\w+\)' -RejectHost 'link closed' -RejectGuest 'link closed','cannot build NPC','bad snapshot'"
  S13 = "-Seconds 70 $link -HostAfterMap '+wait 100' -ExpectHost 'COOP: guest entered kejim_post' -ExpectGuest 'COOP: world synced' -RejectHost 'link closed' -RejectGuest 'link closed','negative reference count','areaportal of \d+ off by','bad snapshot'"
  S14 = "-Seconds 50 -HostArgs '+coop_host','+coop_cptest CoopCenterPrint' -GuestArgs '+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: guest entered kejim_post' -ExpectGuest 'COOP: server command from host: cp .CoopCenterPrint.' -RejectHost 'link closed' -RejectGuest 'link closed'"
  S15 = "-Seconds 50 $link -HostAfterMap '+wait 100' -ExpectHost 'COOP: guest entered kejim_post','COOP: partner view added to snapshots' -ExpectGuest 'COOP: world synced','COOP: partner view added to snapshots' -RejectHost 'link closed' -RejectGuest 'link closed','bad snapshot'"
  # M4: partner puppets both ways, game commands
  S16 = "-Seconds 50 $link -HostAfterMap '+wait 100' -ExpectHost 'COOP: guest synced','COOP: partner puppet ready \(\w+\)' -ExpectGuest 'COOP: world synced','COOP: partner puppet ready \(kyle\)' -RejectHost 'link closed','bad snapshot','cannot build' -RejectGuest 'link closed','bad snapshot','cannot build'"
  S17 = "-Seconds 50 -HostArgs '+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+set coop_onworld \`"coop_gtest fromguest\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: game command echo fromguest' -ExpectGuest 'COOP: world synced' -RejectHost 'link closed','unknown game command' -RejectGuest 'link closed'"
  # M5: interactions across the ownership boundary
  S19 = "-Seconds 50 -HostArgs '+set g_coopFriendlyFire 1','+set coop_onworld \`"wait 3000; coop_hurt 1 7\`"','+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+set g_coopFriendlyFire 1','+set coop_onworld \`"wait 3000; coop_hurt 1 5; coop_use 1\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: hit on 0 \(player\) for 5 from the partner','COOP: partner used 0 \(player\)' -ExpectGuest 'COOP: hit on 0 \(player\) for 7 from the partner' -RejectHost 'link closed','unknown game command' -RejectGuest 'link closed','unknown game command'"
  # M6: NPC authority moves to the guest and back
  S20 = "-Seconds 70 -HostArgs '+set coop_onworld \`"wait 3000; npc spawn stormtrooper; wait 500; coop_npcgive -1; wait 300; coop_npcs\`"','+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: npc \d+ \(\w+\) -> host' -ExpectGuest 'COOP: npc \d+ \(\w+\) -> guest' -RejectHost 'link closed','transfer failed' -RejectGuest 'link closed','transfer failed'"
  # M8: player 2 is Jan in kejim_post (Kyle has no saber)
  S21 = "-Seconds 50 $link -HostAfterMap '+wait 100' -ExpectHost 'COOP: partner puppet ready \(jan\)|COOP: partner changed to jan' -ExpectGuest 'COOP: player 2 is jan' -RejectHost 'link closed','cannot build' -RejectGuest 'link closed'"
  # M10: respawn next to the partner, saves through the host, level change together
  S22 = "-Seconds 60 -HostArgs '+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+set coop_respawnDelay 2','+set coop_onworld \`"wait 3000; kill\`"','+coop_connect 127.0.0.1:29170' -ExpectGuest 'COOP: respawned next to the partner' -RejectHost 'link closed' -RejectGuest 'link closed','Loading game'"
  S23 = "-Seconds 60 -HostArgs '+coop_host' -HostAfterMap '+set timescale 8','+wait 2000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 3000; save coopguest\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: the guest asked for a save \(coopguest\)' -ExpectGuest 'COOP: only the host saves' -RejectHost 'link closed' -RejectGuest 'link closed'"
  S24 = "-Seconds 90 -HostArgs '+set coop_onworld \`"wait 3000; coop_skiplevel\`"','+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: skipping kejim_post -> kejim_base','Server: kejim_base' -ExpectGuest 'COOP: loading kejim_base from host','Server: kejim_base','COOP: in kejim_base' -RejectHost 'link closed' -RejectGuest 'link closed'"
  # M7: g_coopFriendlyFire 0 (default) - the players do not hurt each other
  S25 = "-Seconds 50 -HostArgs '+set coop_onworld \`"wait 3000; coop_hurt 1 7\`"','+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: guest synced' -ExpectGuest 'COOP: world synced' -RejectHost 'link closed' -RejectGuest 'link closed','COOP: hit on 0'"
  # M11: LAN discovery fills the menu's address
  S26 = "-Seconds 30 -GuestNoMap -HostArgs '+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+wait 3000','+coop_find','+wait 3000','+coop_find' -ExpectGuest 'COOP: found \`"HostBot\`" at [0-9.:]+, map kejim_post','COOP: [1-9] game\(s\) found' -RejectHost 'link closed'"
  # bug: enemies ignored the guest (a migrated NPC had no clipmask on the guest and fell through the floor)
  S27 = "-Seconds 60 -HostArgs '+set coop_onworld \`"wait 4000; notarget; npc spawn stormtrooper\`"','+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 3500; setviewpos 1480 -1692 -16 0; wait 8000; coop_entinfo 0\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: guest synced' -ExpectGuest 'COOP: npc \d+ \(stormtrooper\) -> guest','COOP: entinfo 0 owner 2 class player .* health ([0-9]|[1-9][0-9]) origin' -RejectHost 'link closed' -RejectGuest 'link closed'"
  # bug: the host lost the guest's puppet after the intro; a missing partner player is asked for again
  S28 = "-Seconds 50 -HostArgs '+set coop_onworld \`"wait 3000; coop_droppuppet; wait 3000; coop_entinfo 1\`"','+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: puppet dropped','COOP: entinfo 1 owner 2 class player' -RejectHost 'link closed','COOP: no partner snapshot applied','COOP: no snapshot sent' -RejectGuest 'link closed','COOP: no partner snapshot applied','COOP: no snapshot sent'"
  # bug: enemies went for the far host - mission scripts "set_enemy kyle", hits from the guest were dropped, the hidden stand-in fought
  S29 = "-Seconds 60 -HostArgs '+set coop_debug 1','+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 2000; setviewpos 640 -1796 -16 180; wait 500; coop_hurt 298 5; wait 6000; coop_entinfo 0\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: npc 298 \(stormtrooper\) enemy -1 -> 1, run by host' -ExpectGuest 'COOP: npc 298 \(stormtrooper\) -> guest','COOP: entinfo 0 owner 2 class player .* health ([0-9]|[1-9][0-9]) origin' -RejectHost 'link closed','npc 298 \(stormtrooper\) enemy -?1 -> 0, run by host','npc 110 \(jan\) enemy -1 -> 298' -RejectGuest 'link closed'"
  # design 19: weapons are per player - the guest takes the host's dropped blaster, the host does not get it, still sees it and takes it later
  S30 = "-Seconds 50 -HostArgs '+set coop_onworld \`"wait 1000; coop_dropitem weapon_blaster 1500 -1600 -20; wait 6000; coop_entinfo -1; setviewpos 1500 -1600 -16 0; wait 1000; coop_entinfo -1\`"','+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 3000; setviewpos 1500 -1600 -16 0; wait 500; setviewpos 1756 -1692 -16 0; wait 1500; coop_entinfo -1\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: entinfo \d+ owner 1 class weapon_blaster .* hidden 0','Obtained E11','COOP: entinfo \d+ owner -1 class \(free\)' -ExpectGuest 'COOP: picked up weapon_blaster \(the partner decided\)','COOP: entinfo \d+ owner 1 class weapon_blaster .* hidden 1' -RejectHost 'link closed','COOP: picked up' -RejectGuest 'link closed'"
  # bug: an NPC without a saber run by the guest carried the host's puppet as its saber (saberEntityNum 0 swapped to 1)
  S31 = "-Seconds 45 -HostArgs '+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 2000; setviewpos 640 -1796 -16 180; wait 500; coop_hurt 298 5; wait 3000; coop_entinfo 1\`"','+coop_connect 127.0.0.1:29170' -ExpectGuest 'COOP: npc 298 \(stormtrooper\) -> guest','COOP: entinfo 1 owner 1 class player npc .kyle. .* origin 1692 -1692' -RejectHost 'link closed' -RejectGuest 'link closed'"
  # bug: a partner body we are inside (the delay lets them overlap) held our player in the air for good
  S32 = "-Seconds 45 -HostArgs '+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 2500; god; setviewpos 1692 -1692 -16 0; wait 300; +moveright; wait 400; -moveright; coop_entinfo 0\`"','+coop_connect 127.0.0.1:29170' -ExpectGuest 'COOP: entinfo 0 owner 2 class player .* origin 1692 -(19|2\d)\d\d -40' -RejectHost 'link closed' -RejectGuest 'link closed'"
  # bug: an officer the host runs was immortal for the guest - an NPC replica took no shots (takedamage 0)
  S33 = "-Seconds 35 -HostArgs '+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 300; coop_entinfo 297\`"','+coop_connect 127.0.0.1:29170' -ExpectGuest 'COOP: entinfo 297 owner 1 class NPC .* takedamage 1' -RejectHost 'link closed' -RejectGuest 'link closed'"
  # bug: stutters - the partner arrow registered an archived cvar every frame, the config file was rewritten (0.2-2 s) again and again
  S34 = "-Seconds 70 -HostArgs '+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 200; god; setviewpos -450 -684 40 0; wait 6000; coop_entinfo 0\`"','+coop_connect 127.0.0.1:29170' -ExpectGuest 'COOP: entinfo 0 owner 2' -RejectHost 'link closed','hitch, a frame took ([3-9]\d\d|\d\d\d\d+) ms' -RejectGuest 'link closed','hitch, a frame took ([3-9]\d\d|\d\d\d\d+) ms'"
  # bug: doors did not work for the guest - a tap of use at a switch (USE_BUTTON trigger) never reached the host
  S35 = "-Seconds 60 -HostArgs '+set coop_onworld \`"wait 6000; coop_ents trigger_once\`"','+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 1500; god; setviewpos 1160 -250 -600 270; wait 300; +use; wait 2; -use; wait 150; +use; wait 2; -use; wait 150; +use; wait 2; -use; wait 150; +use; wait 2; -use\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: ent 270 trigger_once .* contents 0x0 ' -RejectHost 'link closed' -RejectGuest 'link closed'"
  # bug: the host never respawned - every spot next to the partner was "taken" by the partner itself (the trace started inside it)
  S36 = "-Seconds 120 -HostArgs '+set coop_respawnDelay 2','+set coop_onworld \`"wait 15000; kill\`"','+coop_host' -GuestArgs '+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: our player died, the partner lives','COOP: respawned next to the partner' -RejectHost 'link closed' -RejectGuest 'link closed'"
  # bug: the side door to the tower never opened - a trooper killed on the guest (head shot) died there only, the host's st_death counter never counted it
  S37 = "-Seconds 45 -HostArgs '+coop_host' -HostAfterMap '+set timescale 8','+wait 3000','+set timescale 1' -GuestArgs '+set coop_onworld \`"wait 2000; god; setviewpos 640 -1796 -16 180; wait 500; coop_hurt 298 5; wait 3000; coop_npcs; coop_hurt 298 0 16; wait 500; coop_npcs\`"','+coop_connect 127.0.0.1:29170' -ExpectGuest 'COOP: npcs host \d+ guest [1-9]','COOP: npc 298 \(stormtrooper\) killed here, it dies on the host' -ExpectHost 'COOP: npc 298 \(stormtrooper\) -> host','COOP: npc 298 \(stormtrooper\) killed on the guest by 1' -RejectHost 'link closed','death from the guest lost' -RejectGuest 'link closed'"
  S18 ="-Seconds 50 -HostArgs '+set coop_onworld \`"wait 3000; coop_entinfo 1\`"','+coop_host' -HostAfterMap '+wait 100' -GuestArgs '+set coop_onworld \`"wait 500; setviewpos -100 200 30 0\`"','+coop_connect 127.0.0.1:29170' -ExpectHost 'COOP: entinfo 1 owner 2 class player .* origin -100 200' -ExpectGuest 'COOP: world synced' -RejectHost 'link closed' -RejectGuest 'link closed'"
}
$failed = @()
foreach ($id in $tests.Keys) {
  if ($Only.Count -and $Only -notcontains $id) { continue }
  $out = powershell -ExecutionPolicy Bypass -Command "& '$PSScriptRoot\run-pair.ps1' $($tests[$id])" 2>&1
  $last = ($out | Select-Object -Last 1)
  if ("$last" -eq "SMOKE PASS") { Write-Host "$id PASS" }
  else { Write-Host "$id FAIL"; $out | Where-Object { "$_" -match '^\[FAIL\]' } | ForEach-Object { Write-Host "    $_" }; $failed += $id }
}
if ($failed.Count) { Write-Host "FAILED: $($failed -join ', ')"; exit 1 }
Write-Host "ALL SMOKES PASS"
exit 0
